/**
 * /tmp/adversarial-poc-m1.js
 * Comprehensive Empirical Adversarial Stress Test Harness for Milestone 1
 * Targets: poc/service/ (embedded Node 12 proxy) & dist_poc/com.cinejoy.poc_1.0.0_all.ipk
 */

'use strict';

const http = require('http');
const https = require('https');
const fs = require('fs');
const path = require('path');
const { spawn, execSync } = require('child_process');
const crypto = require('crypto');
const { URL } = require('url');

const POC_SERVICE_DIR = path.resolve(__dirname, '../home/prem/webos-projects/cinejoy-webos/poc/service');
const POC_APP_DIR = path.resolve(__dirname, '../home/prem/webos-projects/cinejoy-webos/poc/app');
const IPK_PATH = path.resolve(__dirname, '../home/prem/webos-projects/cinejoy-webos/dist_poc/com.cinejoy.poc_1.0.0_all.ipk');
const ORIGINAL_WASM = path.resolve(__dirname, '../home/prem/webos-projects/cinejoy-webos/server/crush.wasm');

const TEST_PORT = 8092;
let activeServerProcess = null;

const results = [];
let passCount = 0;
let failCount = 0;

function logHeader(title) {
  console.log('\n' + '='.repeat(70));
  console.log('   ' + title);
  console.log('='.repeat(70));
}

function recordResult(name, pass, details, durationMs) {
  if (pass) {
    passCount++;
    console.log(`  [✔ PASS] ${name} (${durationMs || 0}ms)`);
  } else {
    failCount++;
    console.log(`  [✖ FAIL] ${name} (${durationMs || 0}ms)`);
    if (details) console.log(`      Error: ${details}`);
  }
  results.push({ name, pass, details, durationMs });
}

function makeRequest(opts, body) {
  return new Promise((resolve, reject) => {
    const client = opts.protocol === 'https:' ? https : http;
    const req = client.request(opts, (res) => {
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => {
        const raw = Buffer.concat(chunks);
        let json = null;
        try { json = JSON.parse(raw.toString('utf8')); } catch (_) {}
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          body: raw,
          text: raw.toString('utf8'),
          json: json
        });
      });
    });
    req.on('error', reject);
    if (opts.timeout) {
      req.setTimeout(opts.timeout, () => {
        req.destroy(new Error('Request timed out'));
      });
    }
    if (body) req.write(body);
    req.end();
  });
}

async function sleep(ms) {
  return new Promise(r => setTimeout(r, ms));
}

async function run() {
  logHeader('SECTION 1: STATIC & AST SYNTAX AUDIT FOR FORBIDDEN TOKENS');

  const jsFiles = [
    path.join(POC_SERVICE_DIR, 'index.js'),
    path.join(POC_SERVICE_DIR, 'resolver.js'),
    path.join(POC_SERVICE_DIR, 'hls-proxy.js'),
    path.join(POC_SERVICE_DIR, 'http-client.js'),
    path.join(POC_APP_DIR, 'js/app.js')
  ];

  for (const filePath of jsFiles) {
    const t0 = Date.now();
    const content = fs.readFileSync(filePath, 'utf8');
    const baseName = path.basename(filePath);

    // Strip comments and string literals
    const stripped = content
      .replace(/\/\*[\s\S]*?\*\//g, '')
      .replace(/\/\/.*/g, '')
      .replace(/'(?:[^'\\]|\\.)*'/g, "''")
      .replace(/"(?:[^"\\]|\\.)*"/g, '""')
      .replace(/`(?:[^`\\]|\\.)*`/g, '``');

    const issues = [];
    if (/\?\./.test(stripped)) issues.push('Found optional chaining (?.)');
    if (/\?\?/.test(stripped)) issues.push('Found nullish coalescing (??)');
    if (/\b\d+_\d+\b/.test(stripped)) issues.push('Found numeric separator (_)');
    if (/\b\d+n\b/.test(stripped)) issues.push('Found BigInt literal (n)');
    if (/\bglobalThis\b/.test(stripped)) issues.push('Found globalThis');
    if (filePath.includes('/service/')) {
      if (/\bfetch\s*\(/.test(stripped)) issues.push('Found fetch()');
      if (/\bAbortController\b/.test(stripped)) issues.push('Found AbortController');
      if (/\bAbortSignal\b/.test(stripped)) issues.push('Found AbortSignal');
      if (/\bReadableStream\b/.test(stripped)) issues.push('Found ReadableStream');
    }

    const pass = issues.length === 0;
    recordResult(`Syntax Token Audit: ${baseName}`, pass, issues.join('; '), Date.now() - t0);
  }

  logHeader('SECTION 2: SERVICE LIFECYCLE & PORT COLLISION STRESS');

  const tPortColl = Date.now();
  const dummy = http.createServer((q, s) => s.end('dummy'));
  await new Promise(r => dummy.listen(TEST_PORT, '127.0.0.1', r));

  const serviceProc = spawn('node', [path.join(POC_SERVICE_DIR, 'index.js')], {
    env: Object.assign({}, process.env, { PORT: TEST_PORT.toString() }),
    stdio: 'pipe'
  });
  activeServerProcess = serviceProc;

  let spawnedPort = null;
  for (let i = 0; i < 50; i++) {
    await sleep(100);
    const statusFile = path.join(POC_SERVICE_DIR, '.server-port');
    if (fs.existsSync(statusFile)) {
      const p = parseInt(fs.readFileSync(statusFile, 'utf8').trim(), 10);
      if (p) {
        spawnedPort = p;
        break;
      }
    }
  }

  dummy.close();

  const collisionPass = spawnedPort === (TEST_PORT + 1);
  recordResult(`Port collision detection (auto-fallback ${TEST_PORT} -> ${spawnedPort})`, collisionPass, `Expected port ${TEST_PORT + 1}, got ${spawnedPort}`, Date.now() - tPortColl);

  let proxyPort = spawnedPort || TEST_PORT;

  const tHealth = Date.now();
  const healthRes = await makeRequest({
    hostname: '127.0.0.1',
    port: proxyPort,
    path: '/health',
    method: 'GET'
  });
  const healthPass = healthRes.statusCode === 200 && healthRes.json && healthRes.json.status === 'ok';
  recordResult(`Liveness & Health Probe on port ${proxyPort}`, healthPass, JSON.stringify(healthRes.json), Date.now() - tHealth);

  logHeader('SECTION 3: BOUNDARY & MALFORMED INPUTS (/api/stream)');

  const malformedStreamTests = [
    { name: 'Missing all query parameters', path: '/api/stream', allowedCodes: [400] },
    { name: 'Missing tmdbId parameter', path: '/api/stream?type=movie', allowedCodes: [400] },
    { name: 'Missing type parameter', path: '/api/stream?tmdbId=550', allowedCodes: [400] },
    { name: 'Non-numeric tmdbId (alphanumeric)', path: '/api/stream?tmdbId=abc550&type=movie', allowedCodes: [400] },
    { name: 'Negative tmdbId', path: '/api/stream?tmdbId=-550&type=movie', allowedCodes: [400] },
    { name: 'Floating point tmdbId', path: '/api/stream?tmdbId=550.5&type=movie', allowedCodes: [400] },
    { name: 'SQL injection string in tmdbId', path: '/api/stream?tmdbId=550%20OR%201%3D1&type=movie', allowedCodes: [400] },
    { name: 'XSS script injection in tmdbId', path: '/api/stream?tmdbId=%3Cscript%3Ealert(1)%3C%2Fscript%3E&type=movie', allowedCodes: [400] },
    { name: 'Invalid type parameter (documentary)', path: '/api/stream?tmdbId=550&type=documentary', allowedCodes: [400] },
    { name: 'TV type missing season & episode', path: '/api/stream?tmdbId=1396&type=tv', allowedCodes: [400] },
    { name: 'TV type with season but missing episode', path: '/api/stream?tmdbId=1396&type=tv&season=1', allowedCodes: [400] },
    { name: 'Huge tmdbId (100 digits, overflow rejection)', path: '/api/stream?tmdbId=' + '9'.repeat(100) + '&type=movie', allowedCodes: [400, 500, 502] },
    { name: 'Non-GET method (POST /api/stream)', path: '/api/stream?tmdbId=550&type=movie', method: 'POST', allowedCodes: [200, 400, 502] }
  ];

  for (const tc of malformedStreamTests) {
    const t0 = Date.now();
    try {
      const res = await makeRequest({
        hostname: '127.0.0.1',
        port: proxyPort,
        path: tc.path,
        method: tc.method || 'GET'
      });
      const pass = tc.allowedCodes.indexOf(res.statusCode) !== -1;
      recordResult(`Boundary /api/stream: ${tc.name} -> HTTP ${res.statusCode}`, pass, res.text.substring(0, 150), Date.now() - t0);
    } catch (err) {
      recordResult(`Boundary /api/stream: ${tc.name}`, false, err.message, Date.now() - t0);
    }
  }

  logHeader('SECTION 4: BOUNDARY, MALFORMED & SSRF TESTS (/hls/proxy)');

  const ssrfTests = [
    { name: 'Missing url parameter', path: '/hls/proxy', allowedCodes: [400] },
    { name: 'Empty url parameter', path: '/hls/proxy?url=', allowedCodes: [400] },
    { name: 'File scheme (file:///etc/passwd)', path: '/hls/proxy?url=' + encodeURIComponent('file:///etc/passwd'), allowedCodes: [400] },
    { name: 'Gopher scheme (gopher://127.0.0.1:8088/)', path: '/hls/proxy?url=' + encodeURIComponent('gopher://127.0.0.1:8088/'), allowedCodes: [400] },
    { name: 'FTP scheme (ftp://speedtest.tele2.net/1MB.zip)', path: '/hls/proxy?url=' + encodeURIComponent('ftp://speedtest.tele2.net/1MB.zip'), allowedCodes: [400] },
    { name: 'Javascript pseudo-protocol', path: '/hls/proxy?url=' + encodeURIComponent('javascript:alert(1)'), allowedCodes: [400] },
    { name: 'Unparseable URL (http://)', path: '/hls/proxy?url=' + encodeURIComponent('http://'), allowedCodes: [400] },
    { name: 'Malformed URL encoding (invalid percent encoding)', path: '/hls/proxy?url=%FF%FE%FD', allowedCodes: [400] },
    { name: 'Oversized target URL (8000 chars gracefully handled)', path: '/hls/proxy?url=' + encodeURIComponent('http://example.com/' + 'a'.repeat(8000)), allowedCodes: [400, 404, 414, 502] }
  ];

  for (const tc of ssrfTests) {
    const t0 = Date.now();
    try {
      const res = await makeRequest({
        hostname: '127.0.0.1',
        port: proxyPort,
        path: tc.path,
        method: 'GET'
      });
      const pass = tc.allowedCodes.indexOf(res.statusCode) !== -1;
      recordResult(`SSRF/Boundary /hls/proxy: ${tc.name} -> HTTP ${res.statusCode}`, pass, res.text.substring(0, 150), Date.now() - t0);
    } catch (err) {
      recordResult(`SSRF/Boundary /hls/proxy: ${tc.name}`, false, err.message, Date.now() - t0);
    }
  }

  logHeader('SECTION 5: RAPID CONCURRENCY & EVENT LOOP RESPONSIVENESS');

  const CONCURRENT_REQUESTS = 50;
  const tConcStart = Date.now();
  const promises = [];

  for (let i = 0; i < CONCURRENT_REQUESTS; i++) {
    promises.push(makeRequest({
      hostname: '127.0.0.1',
      port: proxyPort,
      path: '/health',
      method: 'GET'
    }));
  }

  const concResults = await Promise.all(promises);
  const totalConcTime = Date.now() - tConcStart;
  const successfulConc = concResults.filter(r => r.statusCode === 200).length;
  const avgLatency = (totalConcTime / CONCURRENT_REQUESTS).toFixed(2);

  const concPass = successfulConc === CONCURRENT_REQUESTS && totalConcTime < 2000;
  recordResult(`Burst Concurrency (${CONCURRENT_REQUESTS} requests, total ${totalConcTime}ms, avg ${avgLatency}ms/req, ${successfulConc}/${CONCURRENT_REQUESTS} OK)`, concPass, null, totalConcTime);

  const tLoopStart = Date.now();
  await new Promise(r => setImmediate(r));
  const eventLoopLag = Date.now() - tLoopStart;
  const lagPass = eventLoopLag < 20;
  recordResult(`Event Loop Lag immediately post-burst (${eventLoopLag}ms)`, lagPass, `Lag ${eventLoopLag}ms`, eventLoopLag);

  logHeader('SECTION 6: SOCKET ABORT & PREMATURE CLIENT DISCONNECT STRESS');

  const streamRes = await makeRequest({
    hostname: '127.0.0.1',
    port: proxyPort,
    path: '/api/stream?tmdbId=550&type=movie&server=secret',
    method: 'GET'
  });

  let originalPlaylistUrl = streamRes.json && streamRes.json.originalUrl;
  let testMediaUrl = null;

  if (originalPlaylistUrl) {
    const plRes = await makeRequest({
      hostname: '127.0.0.1',
      port: proxyPort,
      path: '/hls/proxy?url=' + encodeURIComponent(originalPlaylistUrl),
      method: 'GET'
    });
    const lines = plRes.text.split('\n');
    for (const l of lines) {
      if (l.includes('/hls/proxy?url=')) {
        const u = l.match(/url=([^"'\s]+)/);
        if (u) {
          testMediaUrl = decodeURIComponent(u[1]);
          break;
        }
      }
    }
  }

  if (!testMediaUrl) {
    testMediaUrl = originalPlaylistUrl || 'https://lightspeed.st/health';
  }

  const memBeforeRes = await makeRequest({
    hostname: '127.0.0.1',
    port: proxyPort,
    path: '/health',
    method: 'GET'
  });
  const rssBefore = memBeforeRes.json && memBeforeRes.json.memory && memBeforeRes.json.memory.rss;

  const ABORT_COUNT = 15;
  const tAbortStart = Date.now();
  let completedAborts = 0;

  for (let i = 0; i < ABORT_COUNT; i++) {
    await new Promise((resolve) => {
      const clientReq = http.get({
        hostname: '127.0.0.1',
        port: proxyPort,
        path: '/hls/proxy?url=' + encodeURIComponent(testMediaUrl)
      }, (res) => {
        res.on('data', () => {
          clientReq.destroy();
          completedAborts++;
          resolve();
        });
      });
      clientReq.on('error', () => {
        resolve();
      });
      setTimeout(() => {
        try { clientReq.destroy(); } catch (_) {}
        resolve();
      }, 500);
    });
  }

  const abortTime = Date.now() - tAbortStart;

  await sleep(200);
  const memAfterRes = await makeRequest({
    hostname: '127.0.0.1',
    port: proxyPort,
    path: '/health',
    method: 'GET'
  });

  const rssAfter = memAfterRes.json && memAfterRes.json.memory && memAfterRes.json.memory.rss;
  const rssDiffMB = ((rssAfter - rssBefore) / (1024 * 1024)).toFixed(2);
  const postAbortHealthy = memAfterRes.statusCode === 200 && memAfterRes.json.status === 'ok';

  recordResult(`Premature Client Aborts (${ABORT_COUNT} destroyed sockets in ${abortTime}ms)`, completedAborts >= ABORT_COUNT - 2, `Completed ${completedAborts}/${ABORT_COUNT}`, abortTime);
  recordResult(`Server Resilience Post-Abort (Liveness OK, RSS delta: ${rssDiffMB} MB)`, postAbortHealthy, `Status: ${memAfterRes.statusCode}`, Date.now() - tAbortStart);

  logHeader('SECTION 7: HTTP RANGE REQUEST & ISO BMFF HEADER STREAMING');

  const tRange = Date.now();
  // Fetch initial bytes of media chunk using HTTP Range
  const rangeRes = await makeRequest({
    hostname: '127.0.0.1',
    port: proxyPort,
    path: '/hls/proxy?url=' + encodeURIComponent(testMediaUrl),
    method: 'GET',
    headers: { 'Range': 'bytes=0-1023' }
  });

  const rangePass = (rangeRes.statusCode === 206 || rangeRes.statusCode === 200) && rangeRes.body.length > 0;
  recordResult(`HTTP 206 Partial Content Range streaming (received ${rangeRes.body.length} bytes)`, rangePass, `Status: ${rangeRes.statusCode}`, Date.now() - tRange);

  logHeader('SECTION 8: IPK PACKAGE INTEGRITY & AR CHECKSUM VERIFICATION');

  const tIpk = Date.now();
  let ipkPass = true;
  const ipkIssues = [];

  if (!fs.existsSync(IPK_PATH)) {
    ipkPass = false;
    ipkIssues.push(`IPK not found at ${IPK_PATH}`);
  } else {
    const ipkStat = fs.statSync(IPK_PATH);
    if (ipkStat.size < 40000) {
      ipkPass = false;
      ipkIssues.push(`IPK size unexpectedly small: ${ipkStat.size} bytes`);
    }

    const arListing = execSync(`ar t ${IPK_PATH}`, { encoding: 'utf8' }).trim().split(/\r?\n/);
    if (!arListing.includes('debian-binary') || !arListing.includes('control.tar.gz') || !arListing.includes('data.tar.gz')) {
      ipkPass = false;
      ipkIssues.push(`Missing standard ar members: ${arListing.join(', ')}`);
    }

    const dataListing = execSync(`tar -ztvf <(ar p ${IPK_PATH} data.tar.gz)`, { shell: '/bin/bash', encoding: 'utf8' });
    const requiredInIpk = [
      'usr/palm/applications/com.cinejoy.poc/appinfo.json',
      'usr/palm/applications/com.cinejoy.poc/index.html',
      'usr/palm/applications/com.cinejoy.poc/js/app.js',
      'usr/palm/services/com.cinejoy.poc.service/services.json',
      'usr/palm/services/com.cinejoy.poc.service/package.json',
      'usr/palm/services/com.cinejoy.poc.service/index.js',
      'usr/palm/services/com.cinejoy.poc.service/resolver.js',
      'usr/palm/services/com.cinejoy.poc.service/hls-proxy.js',
      'usr/palm/services/com.cinejoy.poc.service/http-client.js',
      'usr/palm/services/com.cinejoy.poc.service/crush.wasm'
    ];

    for (const reqFile of requiredInIpk) {
      if (!dataListing.includes(reqFile)) {
        ipkPass = false;
        ipkIssues.push(`Missing file in data.tar.gz: ${reqFile}`);
      }
    }

    const extractedWasm = execSync(`ar p ${IPK_PATH} data.tar.gz | tar -zx -O usr/palm/services/com.cinejoy.poc.service/crush.wasm`);
    const origWasm = fs.readFileSync(ORIGINAL_WASM);

    const hashExtracted = crypto.createHash('sha256').update(extractedWasm).digest('hex');
    const hashOrig = crypto.createHash('sha256').update(origWasm).digest('hex');

    if (hashExtracted !== hashOrig) {
      ipkPass = false;
      ipkIssues.push(`WASM hash mismatch! Original: ${hashOrig}, Extracted: ${hashExtracted}`);
    } else {
      console.log(`      WASM SHA-256 Verified: ${hashExtracted.substring(0, 16)}...`);
    }
  }

  recordResult('IPK Package Structure & Asset Integrity (crush.wasm SHA-256 match)', ipkPass, ipkIssues.join('; '), Date.now() - tIpk);

  // Shutdown test service
  if (activeServerProcess) {
    activeServerProcess.kill('SIGTERM');
  }

  logHeader('TEST SUMMARY & VERDICT');
  console.log(`  Total Checks:  ${results.length}`);
  console.log(`  Passed:        ${passCount}`);
  console.log(`  Failed:        ${failCount}`);
  console.log(`  Success Rate:  ${((passCount / results.length) * 100).toFixed(1)}%`);

  if (failCount === 0) {
    console.log('\nVERDICT: APPROVE (100% EMPIRICAL STRESS TEST SUCCESS)');
    process.exit(0);
  } else {
    console.log(`\nVERDICT: CHALLENGE_FAILED (${failCount} failures detected)`);
    process.exit(1);
  }
}

run().catch(err => {
  console.error('Fatal test error:', err);
  if (activeServerProcess) activeServerProcess.kill();
  process.exit(1);
});
